function report = c_long_lines(data)
%C_LONG_LINES Build a text report from the measurement data.
%   Long lines are kept on purpose: this file mirrors an export template.

% This comment documents the export format used by the lab instrument team: each record carries a site code, a sampling date, a sensor serial number, the raw count, the calibrated value, the uncertainty estimate, the operator initials and a free-text remark field, and the whole record is written on one line so that the downstream importer can split it on tab characters without any further parsing logic at all, which is why the line is so long.

header = ['site,date,serial,raw_count,calibrated,uncertainty,operator,remark,flags,quality_code,batch_id,checksum,revision,status_text'];
prefix = ['Export generated by c_long_lines for dataset ' data.name ' at ' datestr(now) ' with schema version 3.2 and ' num2str(numel(data.values)) ' values in total'];

% A long matrix literal on one line
calibrationTable = [0.00 0.12 0.25 0.37 0.51 0.66 0.80 0.95 1.11 1.28 1.46 1.65 1.85 2.06 2.28 2.51 2.75 3.00 3.26 3.53 3.81 4.10 4.40 4.71 5.03 5.36 5.70 6.05 6.41 6.78 7.16 7.55 7.95 8.36 8.78 9.21 9.65 10.10];

% Long function call with many arguments
report = struct('header', header, 'prefix', prefix, 'table', calibrationTable, ...
    'count', numel(data.values), 'mean', mean(data.values, 'omitnan'), 'maxValue', max(data.values), 'minValue', min(data.values), 'unit', data.unit, 'created', datestr(now), 'author', data.author);

% Concatenate the lines of the body
body = ['Site ' data.site ' reported ' num2str(data.values(1)) ' on the first sample and ' num2str(data.values(end)) ' on the last sample of the acquisition window, ' 'with an overall drift of ' num2str(data.values(end) - data.values(1)) ' units across the full run, which the operator flagged for review.'];
report.body = body;

% Remarks and footer text
footer = sprintf('End of report. Total records: %d. Generated by %s on %s. Please contact the instrument team if any value above is outside the calibrated range given in the table header.', numel(data.values), data.author, datestr(now));
report.footer = footer;

% Long comparison expression
isValid = all(data.values > 0) && all(data.values < 1000) && numel(data.values) >= 10 && ~any(isnan(data.values)) && ~any(isinf(data.values)) && strcmp(data.unit, 'mV');
report.valid = isValid;

% Long string with many pieces
label = ['Sensor ' data.serial ' calibrated at ' data.calDate ' by ' data.calBy ' using reference ' data.refId ' with tolerance ' num2str(data.tol) ' and temperature ' num2str(data.tempC) ' C, humidity ' num2str(data.rh) ' percent, pressure ' num2str(data.hPa) ' hPa.'];
report.label = label;

% Keep the header in the output
report.lines = {header; prefix; body; footer; label};
end
